import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());

        long n = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());
        long l = Long.parseLong(st.nextToken());
        long r = Long.parseLong(st.nextToken());

        long totalCells = n * m;

        if (totalCells % 2 == 0) {
            long halfRange = (r - l + 1) / 2;
            if ((r - l) % 2 == 0 && l % 2 == 0) {
                halfRange++;
            }
            long evenCount = halfRange;
            long oddCount = (r - l + 1) - evenCount;

            Map<Long, Long> dpZero = new HashMap<>();
            Map<Long, Long> dpOne = new HashMap<>();

            pw.println(computeDP(totalCells, 0, evenCount, oddCount, dpZero, dpOne));
        } else {
            long answer = powMod(r - l + 1, totalCells);
            pw.println(answer);
        }
        pw.flush();
        pw.close();
    }

    static long computeDP(long n, int x, long even, long odd, Map<Long, Long> dp0, Map<Long, Long> dp1) {
        if (x == 0) {
            if (dp0.containsKey(n)) {
                return dp0.get(n);
            }
            if (n == 1) {
                long res = even;
                dp0.put(n, res);
                return res;
            } else if (n == 2) {
                long res = (even * even + odd * odd) % 998244353;
                dp0.put(n, res);
                return res;
            }
            long a = computeDP(n / 2, 0, even, odd, dp0, dp1);
            long b = computeDP(n - n / 2, 0, even, odd, dp0, dp1);
            long c = computeDP(n / 2, 1, even, odd, dp0, dp1);
            long d = computeDP(n - n / 2, 1, even, odd, dp0, dp1);
            long res = (a * b + c * d) % 998244353;
            dp0.put(n, res);
            return res;
        } else {
            if (dp1.containsKey(n)) {
                return dp1.get(n);
            }
            if (n == 1) {
                long res = odd;
                dp1.put(n, res);
                return res;
            } else if (n == 2) {
                long res = (even * odd + odd * even) % 998244353;
                dp1.put(n, res);
                return res;
            }
            long a = computeDP(n / 2, 0, even, odd, dp0, dp1);
            long b = computeDP(n - n / 2, 1, even, odd, dp0, dp1);
            long c = computeDP(n / 2, 1, even, odd, dp0, dp1);
            long d = computeDP(n - n / 2, 0, even, odd, dp0, dp1);
            long res = (a * b + c * d) % 998244353;
            dp1.put(n, res);
            return res;
        }
    }

    static long powMod(long base, long exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % 998244353;
            base = (base * base) % 998244353;
            exp >>= 1;
        }
        return res;
    }
}
